create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),name text,email text not null unique,password_hash text not null,phone text,role text not null check(role in ('student','admin','faculty')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists students(id uuid primary key default gen_random_uuid(),user_id uuid unique references users(id) on delete cascade,student_number text unique,program text,status text default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists departments(id uuid primary key default gen_random_uuid(),name text not null unique,code text unique,description text,is_active boolean default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists courses(id uuid primary key default gen_random_uuid(),department_id uuid references departments(id) on delete set null,title text not null unique,code text unique,duration text,description text,fees numeric(12,2) check(fees>=0),is_active boolean default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists admissions(id uuid primary key default gen_random_uuid(),student_name text not null,dob date not null,gender text not null,email text not null,phone text not null,address text not null,previous_qualification text not null,marks_percentage numeric(5,2) not null check(marks_percentage between 0 and 100),course_id text,status text not null default 'pending' check(status in ('pending','approved','rejected','waitlisted')),documents jsonb default '[]'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(email,course_id));
create table if not exists enquiries(id uuid primary key default gen_random_uuid(),name text not null,email text not null,phone text not null,course_interest text,message text not null,status text default 'new' check(status in ('new','contacted','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists faculty(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete set null,department_id uuid references departments(id) on delete set null,name text not null,title text,designation text,email text,bio text,image_url text,is_active boolean default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists events(id uuid primary key default gen_random_uuid(),title text not null,description text,event_date timestamptz not null,location text,image_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists announcements(id uuid primary key default gen_random_uuid(),title text not null,body text not null,category text,is_published boolean default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists gallery(id uuid primary key default gen_random_uuid(),title text not null,image_url text not null,caption text,display_order integer default 0,is_published boolean default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
do $$ declare t text; begin foreach t in array array['users','students','departments','courses','admissions','enquiries','faculty','events','announcements','gallery'] loop execute format('drop trigger if exists set_updated_at on %I',t); execute format('create trigger set_updated_at before update on %I for each row execute function set_updated_at()',t); end loop; end $$;
alter table users enable row level security; alter table students enable row level security; alter table admissions enable row level security; alter table enquiries enable row level security; alter table faculty enable row level security; alter table departments enable row level security; alter table courses enable row level security; alter table events enable row level security; alter table announcements enable row level security; alter table gallery enable row level security;
create policy public_read_courses on courses for select using(is_active); create policy public_read_departments on departments for select using(is_active); create policy public_read_faculty on faculty for select using(is_active); create policy public_read_events on events for select using(true); create policy public_read_announcements on announcements for select using(is_published); create policy public_read_gallery on gallery for select using(is_published);
